css:
@layer component-library {
  @font-face { font-family: NOAVideo; src: url("data:application/font-woff;charset=utf-8;base64,") format("woff"); font-weight: normal; font-style: normal; }
  @media screen and (hover: none) and (pointer: coarse) {
  body::before { content: ""; position: fixed; bottom: 0px; left: 0px; right: 0px; height: 100px; background: linear-gradient(to top, rgba(0, 0, 0, 0.01), rgba(0, 0, 0, 0)); pointer-events: none; z-index: 9999; }
}
  *, ::before, ::after { box-sizing: border-box; }
  hr { height: 0px; color: inherit; }
  table { text-indent: 0px; border-color: inherit; }
  button, input, optgroup, select, textarea { font-family: inherit; font-size: 100%; font-variation-settings: inherit; line-height: 1; margin: 0px; }
  button, select { text-transform: none; }
  button, [type="button"], [type="reset"], [type="submit"] { appearance: button; }
  legend { padding: 0px; }
  progress { vertical-align: baseline; }
  ::-webkit-inner-spin-button, ::-webkit-outer-spin-button { height: auto; }
  [type="search"] { appearance: textfield; }
  ::-webkit-search-decoration { appearance: none; }
  ::-webkit-file-upload-button { appearance: button; font: inherit; }
  summary { display: list-item; }
  html, body { width: 100%; padding: 0px; margin: 0px; font-family: "Geologica Variable", -apple-system, BlinkMacSystemFont, sans-serif; font-size: 16px; font-weight: 300; font-style: normal; font-variation-settings: "CRSV" 1; line-height: 1.4; color: rgb(72, 72, 72); -webkit-font-smoothing: antialiased; }
  a { color: inherit; text-decoration: none; }
  button { color: inherit; }
  :focus-visible { border-radius: 0.5rem; outline-offset: 4px; outline: 4px solid var(--theme-color-focus); transition: 200ms ease-in-out; }
  [data-focus-invert]:focus-visible { --theme-color-focus: var(--theme-color-white); }
  h1, h2, h3, h4, h5, h6 { font-weight: 600; letter-spacing: 0px; margin: 0px 0px 1em; padding: 0px; }
  h1 { font-size: 1.3125rem; }
  h2 { font-size: 1.125rem; }
  h3 { font-size: 1rem; }
  h4, h5, h6 { font-weight: 600; font-size: 0.875rem; }
  p, ol, ul { font-weight: 300; font-size: 0.875rem; }
  strong, b { font-weight: 600; }
  em, i { font-style: italic; }
  u { text-decoration: underline; }
  caption { font-weight: 300; font-size: 0.75rem; }
  @media (min-width: 431px) {
  h1 { font-size: 1.75rem; line-height: 1.35; }
  h2 { font-size: 1.3125rem; }
  h3 { font-size: 1.125rem; }
  h4, h5, h6 { font-size: 1rem; }
  p, ol, ul { font-size: 1rem; }
  caption { font-size: 0.875rem; }
}
}

@media (min-width: 768px) {
  .ieDxOJ { padding-top: 1.5rem; padding-bottom: 1.5rem; margin-top: 0px; margin-bottom: 0px; background:  0% 0% / cover white; }
}

@media (min-width: 1025px) {
  .gDGBMo { display: grid; grid-template-columns: auto 1fr; gap: 2rem; justify-items: start; }
}

@media (min-width: 1025px) {
  .gYbfBj { display: grid; grid-template-columns: auto minmax(max-content, 1fr); gap: 2rem; justify-items: start; }
}

@media (min-width: 1025px) {
  .ftCEaF { transition: opacity; border-radius: var(--border-radius); box-shadow: rgba(72, 72, 72, 0.15) 0px 4px 16px 0px; }
}

@media (min-width: 1025px) {
  .idrooC { transition: opacity 0.05s; border-radius: var(--border-radius); box-shadow: rgba(72, 72, 72, 0.15) 0px 4px 16px 0px; }
}

@media (min-width: 1025px) {
  .bIoTYh { transition: opacity 0.075s; border-radius: var(--border-radius); box-shadow: rgba(72, 72, 72, 0.15) 0px 4px 16px 0px; }
}

@media (min-width: 1025px) {
  .tlcGE { transition: opacity; border-radius: var(--border-radius); box-shadow: rgba(72, 72, 72, 0.15) 0px 4px 16px 0px; }
}

@media (min-width: 1025px) {
  .eqoNDH { transition: opacity 0.05s; border-radius: var(--border-radius); box-shadow: rgba(72, 72, 72, 0.15) 0px 4px 16px 0px; }
}

@media (min-width: 1025px) {
  .fzTCZI { transition: opacity 0.075s; border-radius: var(--border-radius); box-shadow: rgba(72, 72, 72, 0.15) 0px 4px 16px 0px; }
}

@media (min-width: 768px) {
  .gUKJmP h1, .gUKJmP h2, .gUKJmP h3, .gUKJmP h4, .gUKJmP p { font-size: 1.3125rem; }
}

@media (min-width: 1025px) {
  .erHnCE { justify-content: flex-start; background-color: transparent; border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor; }
}

@media (min-width: 1025px) {
  .jMWIwS { border: 1px solid rgb(218, 218, 218); height: 48px; }
  .jMWIwS:first-child { border-top-left-radius: var(--border-radius); border-top-right-radius: var(--border-radius); }
  .jMWIwS:last-child { border-bottom-left-radius: var(--border-radius); border-bottom-right-radius: var(--border-radius); }
}

@media (min-width: 1025px) {
  .izbgXf { transition: color 200ms ease-in-out; color: rgb(72, 72, 72); text-align: start; }
  .izbgXf:hover { cursor: pointer; color: rgb(230, 0, 18); }
}

